INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "明宣宗在南郊祭祀天地", "description": "宣德八年正月丁卯，明宣宗朱瞻基在南郊举行祭祀天地的大典。", "start_year": 1433, "end_year": 1433, "time_original": "宣德八年正月丁卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5d579d9e-ddc3-508e-bc6f-0a79640b918a"}, {"title": "明廷审录在押囚犯，赦免五千多人", "description": "宣德八年二月壬子，朝廷审录在押囚犯，赦免五千多人。", "start_year": 1433, "end_year": 1433, "time_original": "宣德八年二月壬子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "731e8b8d-2b91-5e49-bfee-83526d2b3a32"}, {"title": "明廷授予曹鼐等人进士资格", "description": "宣德八年三月丙辰，朝廷赐曹鼐等人不同等第的进士资格。", "start_year": 1433, "end_year": 1433, "time_original": "宣德八年三月丙辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c6d2e82e-599a-51de-a38f-dce184c9164f"}, {"title": "明廷命官员善待军士", "description": "宣德八年三月庚辰，朝廷告谕中央和地方官员善待军士，违反者由负责监察的官员查察并奏报治罪。", "start_year": 1433, "end_year": 1433, "time_original": "宣德八年三月庚辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e4626a38-7aed-5ee0-a386-0e9ff0358114"}, {"title": "明廷派使救济两京和豫鲁晋旱灾", "description": "宣德八年春，两京及河南、山东、山西长期干旱，朝廷派遣使者前往赈济。", "start_year": 1433, "end_year": 1433, "time_original": "宣德八年春", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b290c48c-d055-5661-973a-61eed1161022"}, {"title": "明廷颁令减免灾区积欠与当年夏税", "description": "宣德八年四月戊戌，朝廷下诏豁免京省灾区积欠的田租和杂课，免除当年的夏税，并给予一年赋役优免。", "start_year": 1433, "end_year": 1433, "time_original": "宣德八年四月戊戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "33b9fcb6-fc61-54a1-b206-3850f71eb758"}, {"title": "明廷命清理冤狱并宽减部分刑罚", "description": "宣德八年四月，朝廷命查理冤狱，减轻死罪及以下部分刑罚，赦免出逃的军籍工匠。", "start_year": 1433, "end_year": 1433, "time_original": "宣德八年四月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a16ee1ec-c712-5b37-9dc1-4f8b8fed434e"}, {"title": "明廷命地方荐才，并查办贪酷官吏与扰民使臣", "description": "宣德八年四月，朝廷命主管官署分别举荐一名贤良方正的人，并命巡按御史和按察使纠举贪酷官吏及挑起事端的使臣。", "start_year": 1433, "end_year": 1433, "time_original": "宣德八年四月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c473b557-3633-5b0e-8b77-87ff45becd50"}, {"title": "萧授率军平息贵州乌罗战事", "description": "宣德八年五月丁巳，据本纪记载，总兵官都督萧授率军平息贵州乌罗一带与明廷的战事。", "start_year": 1433, "end_year": 1433, "time_original": "宣德八年五月丁巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "fcff849e-d2e3-5278-87c7-5da8402744dd"}, {"title": "山云率军平息宜山战事", "description": "宣德八年五月丁卯，据本纪记载，山云率军平息宜山一带与明廷的战事。", "start_year": 1433, "end_year": 1433, "time_original": "宣德八年五月丁卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "91f4745a-7755-57da-b972-9c592a3323ef"}, {"title": "明宣宗祈雨后作《闵旱诗》给群臣看", "description": "宣德八年六月乙酉，宫廷祈雨仍未见降雨，明宣宗朱瞻基作《闵旱诗》，给群臣看。", "start_year": 1433, "end_year": 1433, "time_original": "宣德八年六月乙酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "65c0a1c8-b456-552d-8adc-5fbf59547d99"}, {"title": "明廷命各地清理并裁决在押案件", "description": "宣德八年六月辛丑，朝廷下诏要求中央和地方官署清理并裁决在押罪囚的案件。", "start_year": 1433, "end_year": 1433, "time_original": "宣德八年六月辛丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5b9ba9a6-e47c-5385-a3bb-49a95c47b8c9"}, {"title": "明廷再次赈济两京及豫鲁晋、湖广饥民", "description": "宣德八年夏，朝廷再次救济两京及河南、山东、山西、湖广的饥民，并豁免税粮。", "start_year": 1433, "end_year": 1433, "time_original": "宣德八年夏", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9d02bbaa-3161-5bc8-9441-f0394ee2b80a"}, {"title": "明廷减免江西水灾所涉税粮", "description": "宣德八年七月壬申，朝廷免除江西水灾所涉的税粮。", "start_year": 1433, "end_year": 1433, "time_original": "宣德八年七月壬申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "96a1992f-29d5-59f7-acf7-cde2eeb671ad"}, {"title": "明廷裁撤京师冗官", "description": "宣德八年八月癸巳，朝廷裁撤京师多余的官员。", "start_year": 1433, "end_year": 1433, "time_original": "宣德八年八月癸巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4c325d6f-fdad-58b7-9349-f62f7a2ff6b7"}, {"title": "西域进献本纪称作麒麟的动物", "description": "宣德八年闰八月辛亥，本纪记西域来使进献了称作麒麟的动物。", "start_year": 1433, "end_year": 1433, "time_original": "宣德八年闰八月辛亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4d1a7ddf-a0a7-5a38-a787-4ef36d2d2900"}, {"title": "礼官请求庆贺进贡与景星，明宣宗未准", "description": "宣德八年闰八月戊午，本纪记天上出现所谓景星。礼官请求表贺，明宣宗未准。", "start_year": 1433, "end_year": 1433, "time_original": "宣德八年闰八月戊午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6c8ab2c5-f175-51bb-af25-c95c7914a971"}, {"title": "明廷派官员审录各地重罪案件", "description": "宣德八年九月乙酉，朝廷派出官员审录各地在押重罪人员的案件。", "start_year": 1433, "end_year": 1433, "time_original": "宣德八年九月乙酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a2aa1f6b-96fa-55b2-8e93-8ee6a2e16b25"}, {"title": "昝卜进犯凉州，被刘广率军击杀", "description": "宣德八年九月己亥，阿鲁台部的昝卜率部进犯凉州，总兵官刘广出兵击杀昝卜。", "start_year": 1433, "end_year": 1433, "time_original": "宣德八年九月己亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6137987a-181a-54cb-80b2-b17e5b00b170"}, {"title": "明廷命司法官宽宥京官过犯", "description": "宣德八年十二月乙亥，朝廷告谕司法官署宽宥京官的过失。", "start_year": 1434, "end_year": 1434, "time_original": "宣德八年十二月乙亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "43e18fc7-ea40-5944-9675-ccf2ea88b250"}, {"title": "本纪汇记宣德八年多地入贡", "description": "宣德八年，暹罗、占城、琉球等地入贡。本纪在年末合记各次来使。 按原历纪年，事情发生在公元1433至1434年之间。", "start_year": null, "end_year": null, "time_original": "宣德八年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2f5c6285-6b7d-5d30-8acb-f9f0e9dbe048"}, {"title": "明宣宗在南郊祭祀天地", "description": "宣德九年正月辛卯，明宣宗朱瞻基在南郊举行祭祀天地的大典。", "start_year": 1434, "end_year": 1434, "time_original": "宣德九年正月辛卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2c30b89e-a69b-50ac-935f-cc71f2148dc9"}, {"title": "明廷赈济凤阳、淮安、扬州和徐州饥民", "description": "宣德九年二月庚戌，朝廷救济凤阳、淮安、扬州和徐州的饥民。", "start_year": 1434, "end_year": 1434, "time_original": "宣德九年二月庚戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "050e4bcf-115f-5a91-ab3b-980e6aea6c3c"}, {"title": "明廷重申两京和鲁晋豫的宽恤令", "description": "宣德九年二月乙卯，朝廷重申两京及山东、山西、河南的宽恤令。", "start_year": 1434, "end_year": 1434, "time_original": "宣德九年二月乙卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "40f67c73-857c-5723-9d16-e5917a70d67b"}, {"title": "山云率军平息思恩战事", "description": "宣德九年三月戊寅，本纪记山云率军平息思恩一带与明廷的战事。", "start_year": 1434, "end_year": 1434, "time_original": "宣德九年三月戊寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "447904c5-942e-5a32-8550-042ffbdeb1a0"}, {"title": "黎利去世的消息传来，明廷命其子麟暂掌安南国事", "description": "宣德九年四月己未，卷九记黎利之子麟来报丧，明廷命其暂掌安南国事。《安南传》说麟派使者报丧，并将黎利去世系于前一年。", "start_year": 1434, "end_year": 1434, "time_original": "宣德九年四月己未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "46b6d8f1-e966-50b4-b031-904edbfd61e0"}, {"title": "明廷审录在押囚犯", "description": "宣德九年四月戊辰，朝廷审录在押囚犯。", "start_year": 1434, "end_year": 1434, "time_original": "宣德九年四月戊辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "559f3169-7c65-5c82-b669-3e4ea02e53fe"}, {"title": "明廷命掩埋暴露在外的遗骸", "description": "宣德九年五月壬午，朝廷下令掩埋暴露在外的遗骸。", "start_year": 1434, "end_year": 1434, "time_original": "宣德九年五月壬午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5f5d0c92-50ab-5042-beaf-891cb06da2eb"}, {"title": "明廷派官到两畿和鲁晋豫督办捕蝗", "description": "宣德九年七月甲申，朝廷派给事中、御史和锦衣卫官员到两畿、山东、山西、河南督办捕蝗。", "start_year": 1434, "end_year": 1434, "time_original": "宣德九年七月甲申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a8bedb49-2eda-5495-9787-4d45ad3c3838"}, {"title": "明廷救济湖广饥民", "description": "宣德九年八月庚戌，朝廷救济湖广的饥民。", "start_year": 1434, "end_year": 1434, "time_original": "宣德九年八月庚戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bbd9daa7-982b-5430-8cfb-e1e868a15ad3"}, {"title": "明廷派官查灾并减免四成秋粮", "description": "宣德九年八月甲子，朝廷命两京、湖广、江西、河南的巡抚、巡按御史和三司官员巡视灾区，减免四成秋粮。", "start_year": 1434, "end_year": 1434, "time_original": "宣德九年八月甲子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2defc7ad-b680-5c3a-8748-6ddff5f49f73"}, {"title": "明廷停止工部采办", "description": "宣德九年八月乙丑，朝廷停止工部的采办事务。", "start_year": 1434, "end_year": 1434, "time_original": "宣德九年八月乙丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e15762b9-689d-5c78-841e-389aadb9d614"}, {"title": "脱欢击杀阿鲁台后向明廷报捷", "description": "宣德九年八月己巳，本纪记瓦剌脱欢进攻并杀死阿鲁台，来向明廷报捷。", "start_year": 1434, "end_year": 1434, "time_original": "宣德九年八月己巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "55c4757d-05ba-5691-a895-63ee40c32775"}, {"title": "明宣宗亲自率军巡边", "description": "宣德九年九月癸未，明宣宗朱瞻基亲自带兵巡视边境。", "start_year": 1434, "end_year": 1434, "time_original": "宣德九年九月癸未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "246d7f9f-6bac-59d8-9cc9-f7a0df5de190"}, {"title": "明宣宗率军通过居庸关", "description": "宣德九年九月乙酉，明宣宗朱瞻基率军通过居庸关。", "start_year": 1434, "end_year": 1434, "time_original": "宣德九年九月乙酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2f44fb7b-e386-5265-8ec0-07df8b45ebe9"}, {"title": "明宣宗在坌道打猎", "description": "宣德九年九月丙戌，明宣宗朱瞻基在坌道狩猎。", "start_year": 1434, "end_year": 1434, "time_original": "宣德九年九月丙戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f471632e-c6d9-5583-9e42-8bcb339c608d"}, {"title": "阿鲁台之子阿卜只俺前来归附", "description": "宣德九年九月乙未，阿鲁台之子阿卜只俺前来归附明廷。", "start_year": 1434, "end_year": 1434, "time_original": "宣德九年九月乙未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b28a10da-fa12-5f22-9c42-5ff1acdf35cb"}, {"title": "明宣宗到洗马林查阅城堡防务", "description": "宣德九年九月丁酉，明宣宗朱瞻基到洗马林，巡阅城堡防务。", "start_year": 1434, "end_year": 1434, "time_original": "宣德九年九月丁酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "fc707b56-94d3-554f-abad-7e0023b9d53d"}, {"title": "明宣宗举行大规模狩猎", "description": "宣德九年九月己亥，巡边期间的明宣宗朱瞻基进行大规模狩猎。", "start_year": 1434, "end_year": 1434, "time_original": "宣德九年九月己亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "73aba665-ea46-5da0-aede-89a6e6e6a49d"}, {"title": "明宣宗巡边后返回宫中", "description": "宣德九年十月丙午，明宣宗朱瞻基巡边后返回宫中。", "start_year": 1434, "end_year": 1434, "time_original": "宣德九年十月丙午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8318d91b-d3fb-573f-88ff-d4a7e6817ec7"}, {"title": "方政率军平息松潘战事", "description": "宣德九年十月丙辰，本纪记都督方政率军平息松潘一带与明廷的战事。", "start_year": 1434, "end_year": 1434, "time_original": "宣德九年十月丙辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0ae582b4-6fd9-54cb-ae9d-eafafcd9b1ca"}, {"title": "明廷停止陕西买马", "description": "宣德九年十月甲子，朝廷停止在陕西买马。", "start_year": 1434, "end_year": 1434, "time_original": "宣德九年十月甲子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "71502dbf-c604-5536-998e-e43825232aba"}, {"title": "明廷调用南京运粮和临清仓粮救荒", "description": "宣德九年十月丁卯，两畿、浙江、湖广、江西发生饥荒。朝廷将应运往南京的粮食与临清仓中的存粮用于赈济。", "start_year": 1434, "end_year": 1434, "time_original": "宣德九年十月丁卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c1e0306d-fb32-5de4-8a7e-94d6e431435b"}, {"title": "明廷停止行刑", "description": "宣德九年十一月戊戌，朝廷命停止行刑。", "start_year": 1435, "end_year": 1435, "time_original": "宣德九年十一月戊戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "494421d7-f6d0-5c88-ab6d-9cba949a35ef"}, {"title": "明廷免除四川受灾地区税粮", "description": "宣德九年十一月庚子，朝廷免除四川受灾地区应缴的税粮。", "start_year": 1435, "end_year": 1435, "time_original": "宣德九年十一月庚子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e291be7c-dcc9-53b5-8900-ff4c7f25dbd9"}, {"title": "明宣宗患病，卫王朱瞻埏代祭太庙", "description": "宣德九年十二月甲子，明宣宗朱瞻基身体不适，由卫王朱瞻埏代行太庙祭祀。", "start_year": 1435, "end_year": 1435, "time_original": "宣德九年十二月甲子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5e01c612-8205-52b1-b6c6-76096912cbd1"}, {"title": "本纪汇记宣德九年多地入贡", "description": "宣德九年，暹罗、占城、琉球、苏门答剌、哈密和瓦剌入贡。 按原历纪年，事情发生在公元1434至1435年之间。", "start_year": null, "end_year": null, "time_original": "宣德九年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7973584a-9820-5a54-b1f1-472a0f3d88d9"}, {"title": "明宣宗正月初一未临朝，命群臣拜见皇太子", "description": "宣德十年正月初一，明宣宗朱瞻基没有临朝，命群臣到文华殿拜见皇太子朱祁镇。", "start_year": 1435, "end_year": 1435, "time_original": "宣德十年正月癸酉朔", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b9de786a-a771-5894-a008-c45030f32af7"}, {"title": "明宣宗病势转重，朝廷撤回采买、营造使者", "description": "宣德十年正月甲戌，明宣宗朱瞻基病势转重。朝廷撤回负责采买、营造的使者。", "start_year": 1435, "end_year": 1435, "time_original": "宣德十年正月甲戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ca624213-4727-5dd8-b2ae-e15559d06042"}, {"title": "明宣宗朱瞻基在乾清宫去世", "description": "宣德十年正月乙亥，明宣宗朱瞻基在乾清宫去世，本纪记享年三十八。", "start_year": 1435, "end_year": 1435, "time_original": "宣德十年正月乙亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d3ce7688-32a8-5b4d-971a-943718c2eaba"}, {"title": "明宣宗遗诏规定国家要务须禀报皇太后", "description": "宣德十年正月，明宣宗的遗诏规定，国家重大事务应禀报皇太后张氏。", "start_year": 1435, "end_year": 1435, "time_original": "宣德十年正月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2a9f33c4-06e7-52ac-91f4-97f38385219a"}, {"title": "明廷为朱瞻基上尊谥，定庙号宣宗", "description": "宣德十年正月丁酉，朝廷为朱瞻基上尊谥，定庙号为宣宗。本纪随后记他安葬于景陵。", "start_year": 1435, "end_year": 1435, "time_original": "宣德十年正月丁酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "39fe4639-e909-5f14-885c-ce9054152711"}, {"title": "黎利在其子向明廷报丧之前去世", "description": "《明史》卷九提到黎利去世，紧接着记他儿子麟向明廷报丧。卷三二一《安南传》将黎利之死系于宣德八年，卷九的四月己未是告丧及朝廷处置的时间。", "start_year": null, "end_year": null, "time_original": "黎利之死在宣德九年四月告丧之前", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "85f77500-f1bf-5c39-8d26-ef4407721046"}, {"title": "薛贵、吴成等率军巡边", "description": "洪熙元年闰七月戊申，安顺伯薛贵、清平伯吴成、都督马英和都指挥梁成率军巡查边境。卷末校记说明「吴成」原误作「吴诚」。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年闰七月戊申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "623b9bc8-f00a-542d-befb-b21accbd1f3a"}, {"title": "明廷派沐晟、柳升分路进军，李庆参赞", "description": "宣德元年十二月乙酉，朝廷命沐晟、柳升分别率兵由云南、广西进军，讨伐黎利。兵部尚书李庆参赞军务。", "start_year": 1427, "end_year": 1427, "time_original": "宣德元年十二月乙酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "376bf95b-4aa4-57d1-aa95-8b758ed6b451"}, {"title": "况钟、何文渊等九人被提拔为知府", "description": "宣德五年五月癸亥，朝廷提拔郎中况钟、御史何文渊等九人担任知府，发下任命文书，派他们赴任。卷末校记说明何文渊官职原脱「御史」二字。", "start_year": 1430, "end_year": 1430, "time_original": "宣德五年五月癸亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "457cd1d4-8ecd-5532-877c-b3a348ec5de9"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

